    # Validación de precondiciones
    if not isinstance(dict_a, dict) or not isinstance(dict_b, dict):
        raise TypeError("Ambos argumentos deben ser diccionarios")

    # Función auxiliar para realizar la fusión de dos diccionarios
    def merge_dicts(a, b):
        merged = a.copy()  # Copia defensiva de dict_a
        for k, v in b.items():
            if k in merged:
                if isinstance(v, dict) and isinstance(merged[k], dict):
                    merged[k] = merge_dicts(merged[k], v)  # Fusiona recursivamente si son diccionarios
                elif isinstance(v, list) and isinstance(merged[k], list):
                    merged[k] = merged[k] + v  # Concatena si son listas
                else:
                    merged[k] = v  # Sobrescribe si son escalares o tipos distintos
            else:
                merged[k] = v  # Incluye solo si no existe en dict_a
        return merged

    # Llamada a la función auxiliar con los argumentos proporcionados
    return merge_dicts(dict_a, dict_b)

