def parse_csv_line(line: str, delimiter: str = ',') -> list[str]:
    # Validación de precondiciones
    if not isinstance(line, str):
        raise TypeError("Line must be a string")
    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("Delimiter must be a single character")

    # Variables para almacenar el resultado y el estado de la lectura
    result = []
    current_field = ""
    in_quote = False
    escape_next = False

    # Iterar sobre cada carácter en la línea
    for char in line:
        if char == '"':
            if escape_next:
                # Si estamos escapando, ignoramos la comilla
                escape_next = False
            elif in_quote:
                # Si estamos dentro de una comilla, terminamos el campo
                in_quote = False
                result.append(current_field)
                current_field = ""
            else:
                # Si no estamos dentro de una comilla, comenzamos una nueva comilla
                in_quote = True
        elif char == delimiter and not in_quote:
            # Si encontramos un delimitador y no estamos dentro de una comilla, terminamos el campo
            result.append(current_field)
            current_field = ""
        elif char == '\\':
            # Si encontramos un backslash, marcamos que el siguiente carácter es escapado
            escape_next = True
        else:
            # Si no estamos dentro de una comilla, simplemente agregamos el carácter al campo actual
            current_field += char

    # Si el último campo no está vacío, lo agregamos al resultado
    if current_field:
        result.append(current_field)

    # Si estamos dentro de una comilla al final de la línea, levantamos un error
    if in_quote:
        raise ValueError("Unterminated quoted field")

    return result

