from typing import Dict, List, Set, Tuple
from collections import defaultdict

def resolve_dependencies(tasks: Dict[str, List[str]]) -> List[str]:
    if not isinstance(tasks, dict):
        raise TypeError("Invalid tasks dictionary type")

    # Helper function to check for cycles using DFS
    def has_cycle(node: str, visited: Set[str], stack: Set[str]) -> bool:
        if node in stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        stack.add(node)
        for neighbor in tasks[node]:
            if has_cycle(neighbor, visited, stack):
                return True
        stack.remove(node)
        return False

    # Check for cycles in the graph
    for task in tasks:
        if has_cycle(task, set(), set()):
            raise ValueError("Circular dependency detected")

    # Topological sort using Kahn's algorithm
    in_degree = defaultdict(int)
    for task, deps in tasks.items():
        for dep in deps:
            in_degree[dep] += 1

    queue = [task for task in tasks if in_degree[task] == 0]
    result = []

    while queue:
        task = queue.pop(0)
        result.append(task)
        for dep in tasks[task]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(dep)

    # Check if all tasks were processed
    if len(result) != len(tasks):
        raise ValueError("Not all tasks were processed")

    return result

